package com.deckbuilder.mtgdeckbuilder.application;

import com.deckbuilder.mtgdeckbuilder.model.Card;
import com.deckbuilder.mtgdeckbuilder.model.Deck;
import com.deckbuilder.mtgdeckbuilder.model.Format;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.Arrays;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
@DisplayName("Deck Validation Service Tests")
class DeckValidationServiceTest {

	@Mock
	private FormatService formatService;

	@Mock
	private CardService cardService;

	@InjectMocks
	private DeckValidationService deckValidationService;

	private Format standardFormat;
	private Format commanderFormat;
	private Card lightningBolt;
	private Card forest;
	private Card blackLotus;
	private Deck testDeck;

	@BeforeEach
	void setUp() {
		// Standard format (60 card minimum, 4-of rule)
		this.standardFormat = Format.builder()
				.id(1L)
				.name("Standard")
				.minDeckSize(60)
				.maxDeckSize(999)
				.maxSideboardSize(15)
				.bannedCards(List.of("Black Lotus"))
				.restrictedCards(List.of())
				.build();

		// Commander format (100 card singleton)
		this.commanderFormat = Format.builder()
				.id(2L)
				.name("Commander")
				.minDeckSize(100)
				.maxDeckSize(100)
				.maxSideboardSize(0)
				.bannedCards(List.of("Black Lotus"))
				.restrictedCards(List.of())
				.build();

		// Test cards
		this.lightningBolt = Card.builder()
				.id(1L)
				.name("Lightning Bolt")
				.typeLine("Instant")
				.cardType("Instant")
				.build();

		this.forest = Card.builder()
				.id(2L)
				.name("Forest")
				.typeLine("Basic Land — Forest")
				.cardType("Land")
				.cardSupertype("Basic")
				.build();

		this.blackLotus = Card.builder()
				.id(3L)
				.name("Black Lotus")
				.typeLine("Artifact")
				.cardType("Artifact")
				.build();

		// Test deck with some cards
		this.testDeck = Deck.builder()
				.id(1L)
				.name("Test Deck")
				.formatId(1L) // Standard
				.cards(Arrays.asList(
						createCardInDeck(1L, 4, "main"), // 4x Lightning Bolt
						createCardInDeck(2L, 20, "main") // 20x Forest
				))
				.build();
	}

	private Deck.CardInDeck createCardInDeck(Long cardId, int quantity, String section) {
		return Deck.CardInDeck.builder()
				.cardId(cardId)
				.quantity(quantity)
				.section(section)
				.build();
	}

	// ========================================
	// Critical Missing: Deck Building Tests
	// ========================================

	@Test
	@DisplayName("Should validate deck size for format")
	void shouldValidateDeckSizeForFormat() {
		// Given
		when(this.formatService.findById(1L)).thenReturn(java.util.Optional.of(this.standardFormat));

		// When
		final boolean isValid = this.deckValidationService.isDeckSizeValid(this.testDeck);

		// Then
		assertThat(isValid).isFalse(); // 24 cards < 60 minimum
	}

	@Test
	@DisplayName("Should enforce 4-of rule in Standard")
	void shouldEnforce4OfRuleInStandard() {
		// Given
		final Deck invalidDeck = Deck.builder()
				.formatId(1L)
				.cards(List.of(createCardInDeck(1L, 5, "main"))) // 5x Lightning Bolt (invalid)
				.build();

		when(this.formatService.findById(1L)).thenReturn(java.util.Optional.of(this.standardFormat));
		when(this.cardService.findById(1L)).thenReturn(java.util.Optional.of(this.lightningBolt));

		// When
		final boolean isValid = this.deckValidationService.areCardQuantitiesValid(invalidDeck);

		// Then
		assertThat(isValid).isFalse(); // More than 4 copies
	}

	@Test
	@DisplayName("Should allow unlimited basic lands")
	void shouldAllowUnlimitedBasicLands() {
		// Given
		final Deck basicLandDeck = Deck.builder()
				.formatId(1L)
				.cards(List.of(createCardInDeck(2L, 40, "main"))) // 40x Forest
				.build();

		when(this.formatService.findById(1L)).thenReturn(java.util.Optional.of(this.standardFormat));
		when(this.cardService.findById(2L)).thenReturn(java.util.Optional.of(this.forest));

		// When
		final boolean isValid = this.deckValidationService.areCardQuantitiesValid(basicLandDeck);

		// Then
		assertThat(isValid).isTrue(); // Basic lands can exceed 4-of rule
	}

	@Test
	@DisplayName("Should enforce singleton rule in Commander")
	void shouldEnforceSingletonRuleInCommander() {
		// Given
		final Deck commanderDeck = Deck.builder()
				.formatId(2L)
				.cards(List.of(createCardInDeck(1L, 2, "main"))) // 2x Lightning Bolt (invalid in Commander)
				.build();

		when(this.formatService.findById(2L)).thenReturn(java.util.Optional.of(this.commanderFormat));
		when(this.cardService.findById(1L)).thenReturn(java.util.Optional.of(this.lightningBolt));

		// When
		final boolean isValid = this.deckValidationService.areCardQuantitiesValid(commanderDeck);

		// Then
		assertThat(isValid).isFalse(); // Commander allows only 1 copy of non-basic lands
	}

	@Test
	@DisplayName("Should check card legality in format")
	void shouldCheckCardLegalityInFormat() {
		// Given
		final Deck bannedCardDeck = Deck.builder()
				.formatId(1L)
				.cards(List.of(createCardInDeck(3L, 1, "main"))) // 1x Black Lotus (banned)
				.build();

		when(this.formatService.findById(1L)).thenReturn(java.util.Optional.of(this.standardFormat));
		when(this.cardService.findById(3L)).thenReturn(java.util.Optional.of(this.blackLotus));

		// When
		final boolean isValid = this.deckValidationService.areCardsLegalInFormat(bannedCardDeck);

		// Then
		assertThat(isValid).isFalse(); // Black Lotus is banned in Standard
	}

	@Test
	@DisplayName("Should validate sideboard size")
	void shouldValidateSideboardSize() {
		// Given
		final Deck deckWithLargeSideboard = Deck.builder()
				.formatId(1L)
				.cards(Arrays.asList(
						createCardInDeck(1L, 4, "main"),
						createCardInDeck(2L, 20, "sideboard") // 20 cards in sideboard (max 15)
				))
				.build();

		when(this.formatService.findById(1L)).thenReturn(java.util.Optional.of(this.standardFormat));

		// When
		final boolean isValid = this.deckValidationService.isSideboardValid(deckWithLargeSideboard);

		// Then
		assertThat(isValid).isFalse(); // Sideboard exceeds 15 cards
	}

	@Test
	@DisplayName("Should allow choosing specific card variants")
	void shouldAllowChoosingSpecificCardVariant() {
		// Given - Different variants of the same card
		final Card forestVariant1 = this.forest.toBuilder().collectorNumber("264").build();
		final Card forestVariant2 = this.forest.toBuilder().collectorNumber("265").build();

		final Deck variantDeck = Deck.builder()
				.formatId(1L)
				.cards(Arrays.asList(
						createCardInDeck(forestVariant1.getId(), 10, "main"),
						createCardInDeck(forestVariant2.getId(), 10, "main")
				))
				.build();

		when(this.formatService.findById(1L)).thenReturn(java.util.Optional.of(this.standardFormat));
		when(this.cardService.findById(forestVariant1.getId())).thenReturn(java.util.Optional.of(forestVariant1));
		when(this.cardService.findById(forestVariant2.getId())).thenReturn(java.util.Optional.of(forestVariant2));

		// When
		final boolean isValid = this.deckValidationService.areCardQuantitiesValid(variantDeck);

		// Then
		assertThat(isValid).isTrue(); // Different variants are treated as separate cards for basic lands
	}

	@Test
	@DisplayName("Should validate deck even with different variants of non-basic cards")
	void shouldValidateDeckEvenWithDifferentVariantsOfNonBasicCards() {
		// Given - Different variants of Lightning Bolt
		final Card boltRegular = this.lightningBolt.toBuilder().id(10L).collectorNumber("001").build();
		final Card boltFoil = this.lightningBolt.toBuilder().id(11L).collectorNumber("001★").foil(true).build();

		final Deck variantDeck = Deck.builder()
				.formatId(1L)
				.cards(Arrays.asList(
						createCardInDeck(10L, 2, "main"), // 2x regular Lightning Bolt
						createCardInDeck(11L, 2, "main")  // 2x foil Lightning Bolt
				))
				.build();

		when(this.formatService.findById(1L)).thenReturn(java.util.Optional.of(this.standardFormat));
		when(this.cardService.findById(10L)).thenReturn(java.util.Optional.of(boltRegular));
		when(this.cardService.findById(11L)).thenReturn(java.util.Optional.of(boltFoil));

		// When
		final boolean isValid = this.deckValidationService.areCardQuantitiesValidConsideringVariants(variantDeck);

		// Then
		assertThat(isValid).isTrue(); // 4 total Lightning Bolts across variants is valid
	}

	@Test
	@DisplayName("Should invalidate deck when variants exceed 4-of rule")
	void shouldInvalidateDeckWhenVariantsExceed4OfRule() {
		// Given - Too many variants of Lightning Bolt
		final Card boltRegular = this.lightningBolt.toBuilder().id(10L).collectorNumber("001").build();
		final Card boltFoil = this.lightningBolt.toBuilder().id(11L).collectorNumber("001★").foil(true).build();
		final Card boltPromo = this.lightningBolt.toBuilder().id(12L).collectorNumber("001p").promo(true).build();

		final Deck variantDeck = Deck.builder()
				.formatId(1L)
				.cards(Arrays.asList(
						createCardInDeck(10L, 2, "main"), // 2x regular Lightning Bolt
						createCardInDeck(11L, 2, "main"), // 2x foil Lightning Bolt  
						createCardInDeck(12L, 2, "main")  // 2x promo Lightning Bolt = 6 total
				))
				.build();

		when(this.formatService.findById(1L)).thenReturn(java.util.Optional.of(this.standardFormat));
		when(this.cardService.findById(10L)).thenReturn(java.util.Optional.of(boltRegular));
		when(this.cardService.findById(11L)).thenReturn(java.util.Optional.of(boltFoil));
		when(this.cardService.findById(12L)).thenReturn(java.util.Optional.of(boltPromo));

		// When
		final boolean isValid = this.deckValidationService.areCardQuantitiesValidConsideringVariants(variantDeck);

		// Then
		assertThat(isValid).isFalse(); // 6 total Lightning Bolts exceeds 4-of rule
	}

	@Test
	@DisplayName("Should validate complete deck for format compliance")
	void shouldValidateCompleteDeckForFormatCompliance() {
		// Given - Valid 60 card Standard deck
		final Deck validStandardDeck = Deck.builder()
				.formatId(1L)
				.cards(Arrays.asList(
						createCardInDeck(1L, 4, "main"), // 4x Lightning Bolt
						createCardInDeck(2L, 56, "main") // 56x Forest = 60 total
				))
				.build();

		when(this.formatService.findById(1L)).thenReturn(java.util.Optional.of(this.standardFormat));
		when(this.cardService.findById(1L)).thenReturn(java.util.Optional.of(this.lightningBolt));
		when(this.cardService.findById(2L)).thenReturn(java.util.Optional.of(this.forest));

		// When
		final boolean isValid = this.deckValidationService.isValidDeck(validStandardDeck);

		// Then
		assertThat(isValid).isTrue(); // Valid 60-card Standard deck
	}
}

package com.deckbuilder.mtgdeckbuilder.application;

import com.deckbuilder.mtgdeckbuilder.model.Card;
import com.deckbuilder.mtgdeckbuilder.model.Format;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.List;
import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
@DisplayName("Format Legality Service Tests")
class FormatLegalityServiceTest {

	@Mock
	private FormatService formatService;

	@Mock
	private CardService cardService;

	@InjectMocks
	private FormatLegalityService formatLegalityService;

	private Format standardFormat;
	private Format legacyFormat;
	private Format vintageFormat;
	private Card lightningBolt;
	private Card blackLotus;
	private Card brainstorm;
	private Card ancestralRecall;

	@BeforeEach
	void setUp() {
		// Standard format - Black Lotus banned
		this.standardFormat = Format.builder()
				.id(1L)
				.name("Standard")
				.bannedCards(List.of("Black Lotus", "Ancestral Recall"))
				.restrictedCards(List.of())
				.build();

		// Legacy format - Black Lotus banned, Brainstorm legal
		this.legacyFormat = Format.builder()
				.id(2L)
				.name("Legacy")
				.bannedCards(List.of("Black Lotus"))
				.restrictedCards(List.of())
				.build();

		// Vintage format - Black Lotus restricted, Ancestral Recall restricted
		this.vintageFormat = Format.builder()
				.id(3L)
				.name("Vintage")
				.bannedCards(List.of())
				.restrictedCards(List.of("Black Lotus", "Ancestral Recall"))
				.build();

		// Test cards
		this.lightningBolt = Card.builder()
				.id(1L)
				.name("Lightning Bolt")
				.build();

		this.blackLotus = Card.builder()
				.id(2L)
				.name("Black Lotus")
				.build();

		this.brainstorm = Card.builder()
				.id(3L)
				.name("Brainstorm")
				.build();

		this.ancestralRecall = Card.builder()
				.id(4L)
				.name("Ancestral Recall")
				.build();
	}

	// ========================================
	// Critical Missing: Format Legality Tests
	// ========================================

	@Test
	@DisplayName("Should check if card is legal in format")
	void shouldCheckIfCardIsLegalInFormat() {
		// Given
		when(this.formatService.findById(1L)).thenReturn(Optional.of(this.standardFormat));

		// When
		final boolean lightningBoltLegal = this.formatLegalityService.isCardLegalInFormat(this.lightningBolt, 1L);
		final boolean blackLotusLegal = this.formatLegalityService.isCardLegalInFormat(this.blackLotus, 1L);

		// Then
		assertThat(lightningBoltLegal).isTrue(); // Lightning Bolt is legal in Standard
		assertThat(blackLotusLegal).isFalse(); // Black Lotus is banned in Standard
	}

	@Test
	@DisplayName("Should handle banned cards correctly")
	void shouldHandleBannedCardsCorrectly() {
		// Given
		when(this.formatService.findById(1L)).thenReturn(Optional.of(this.standardFormat));
		when(this.formatService.findById(2L)).thenReturn(Optional.of(this.legacyFormat));

		// When
		final boolean blackLotusInStandard = this.formatLegalityService.isCardLegalInFormat(this.blackLotus, 1L);
		final boolean blackLotusInLegacy = this.formatLegalityService.isCardLegalInFormat(this.blackLotus, 2L);

		// Then
		assertThat(blackLotusInStandard).isFalse(); // Banned in Standard
		assertThat(blackLotusInLegacy).isFalse(); // Also banned in Legacy
	}

	@Test
	@DisplayName("Should handle restricted cards correctly")
	void shouldHandleRestrictedCardsCorrectly() {
		// Given
		when(this.formatService.findById(3L)).thenReturn(Optional.of(this.vintageFormat));

		// When
		final boolean blackLotusRestricted = this.formatLegalityService.isCardRestrictedInFormat(this.blackLotus, 3L);
		final boolean ancestralRecallRestricted = this.formatLegalityService.isCardRestrictedInFormat(this.ancestralRecall, 3L);
		final boolean lightningBoltRestricted = this.formatLegalityService.isCardRestrictedInFormat(this.lightningBolt, 3L);

		// Then
		assertThat(blackLotusRestricted).isTrue(); // Black Lotus is restricted in Vintage
		assertThat(ancestralRecallRestricted).isTrue(); // Ancestral Recall is restricted in Vintage
		assertThat(lightningBoltRestricted).isFalse(); // Lightning Bolt is not restricted
	}

	@Test
	@DisplayName("Should get maximum allowed copies in format")
	void shouldGetMaximumAllowedCopiesInFormat() {
		// Given
		when(this.formatService.findById(1L)).thenReturn(Optional.of(this.standardFormat));
		when(this.formatService.findById(3L)).thenReturn(Optional.of(this.vintageFormat));

		// When
		final int lightningBoltInStandard = this.formatLegalityService.getMaxAllowedCopies(this.lightningBolt, 1L);
		final int blackLotusInStandard = this.formatLegalityService.getMaxAllowedCopies(this.blackLotus, 1L);
		final int blackLotusInVintage = this.formatLegalityService.getMaxAllowedCopies(this.blackLotus, 3L);

		// Then
		assertThat(lightningBoltInStandard).isEqualTo(4); // Standard allows 4 copies
		assertThat(blackLotusInStandard).isEqualTo(0); // Banned cards allow 0 copies
		assertThat(blackLotusInVintage).isEqualTo(1); // Restricted cards allow 1 copy
	}

	@Test
	@DisplayName("Should handle basic lands exception")
	void shouldHandleBasicLandsException() {
		// Given
		final Card forest = Card.builder()
				.id(5L)
				.name("Forest")
				.typeLine("Basic Land — Forest")
				.cardSupertype("Basic")
				.build();

		when(this.formatService.findById(1L)).thenReturn(Optional.of(this.standardFormat));

		// When
		final int maxForestCopies = this.formatLegalityService.getMaxAllowedCopies(forest, 1L);

		// Then
		assertThat(maxForestCopies).isEqualTo(-1); // -1 indicates unlimited (basic lands)
	}

	@Test
	@DisplayName("Should validate card legality across multiple formats")
	void shouldValidateCardLegalityAcrossMultipleFormats() {
		// Given
		when(this.formatService.findById(1L)).thenReturn(Optional.of(this.standardFormat));
		when(this.formatService.findById(2L)).thenReturn(Optional.of(this.legacyFormat));
		when(this.formatService.findById(3L)).thenReturn(Optional.of(this.vintageFormat));

		// When
		final boolean brainstormInStandard = this.formatLegalityService.isCardLegalInFormat(this.brainstorm, 1L);
		final boolean brainstormInLegacy = this.formatLegalityService.isCardLegalInFormat(this.brainstorm, 2L);
		final boolean brainstormInVintage = this.formatLegalityService.isCardLegalInFormat(this.brainstorm, 3L);

		// Then
		assertThat(brainstormInStandard).isTrue(); // Legal in Standard (not in banned list)
		assertThat(brainstormInLegacy).isTrue(); // Legal in Legacy
		assertThat(brainstormInVintage).isTrue(); // Legal in Vintage
	}

	@Test
	@DisplayName("Should check format rotation and card legality")
	void shouldCheckFormatRotationAndCardLegality() {
		// Given - Standard format with rotation date
		final Format rotatingStandard = this.standardFormat.toBuilder()
				.description("Standard format with rotation")
				.build();

		when(this.formatService.findById(1L)).thenReturn(Optional.of(rotatingStandard));

		// When
		final boolean cardLegal = this.formatLegalityService.isCardLegalInFormat(this.lightningBolt, 1L);

		// Then
		assertThat(cardLegal).isTrue(); // Card should be legal (rotation logic can be added later)
	}

	@Test
	@DisplayName("Should return format legality summary for card")
	void shouldReturnFormatLegalitySummaryForCard() {
		// Given
		final List<Format> allFormats = List.of(this.standardFormat, this.legacyFormat, this.vintageFormat);
		when(this.formatService.findAll()).thenReturn(allFormats);

		// When
		final var legalitySummary = this.formatLegalityService.getCardLegalityInAllFormats(this.blackLotus);

		// Then
		assertThat(legalitySummary).hasSize(3);
		assertThat(legalitySummary.get("Standard")).isEqualTo("BANNED");
		assertThat(legalitySummary.get("Legacy")).isEqualTo("BANNED");
		assertThat(legalitySummary.get("Vintage")).isEqualTo("RESTRICTED");
	}

	@Test
	@DisplayName("Should handle case-insensitive card name matching")
	void shouldHandleCaseInsensitiveCardNameMatching() {
		// Given - Format with different case in banned list
		final Format caseInsensitiveFormat = Format.builder()
				.id(4L)
				.name("Test Format")
				.bannedCards(List.of("black lotus", "LIGHTNING BOLT"))
				.restrictedCards(List.of())
				.build();

		when(this.formatService.findById(4L)).thenReturn(Optional.of(caseInsensitiveFormat));

		// When
		final boolean blackLotusLegal = this.formatLegalityService.isCardLegalInFormat(this.blackLotus, 4L);
		final boolean lightningBoltLegal = this.formatLegalityService.isCardLegalInFormat(this.lightningBolt, 4L);

		// Then
		assertThat(blackLotusLegal).isFalse(); // Should match "black lotus" (case insensitive)
		assertThat(lightningBoltLegal).isFalse(); // Should match "LIGHTNING BOLT" (case insensitive)
	}
}

package com.deckbuilder.mtgdeckbuilder.contract;

import com.deckbuilder.apigenerator.openapi.api.model.CardDTO;
